const videoDeliveryWorker="/* Only public MP4 delivery. No caches, cookies, admin or API interception. */\nconst CHUNK = 256 * 1024;\nconst PARALLEL = 6;\nself.addEventListener('install', () => self.skipWaiting());\nself.addEventListener('activate', event => event.waitUntil(self.clients.claim()));\nself.addEventListener('fetch', event => {\n  const request = event.request;\n  const url = new URL(request.url);\n  if (url.searchParams.has('direct')) return;\n  if (request.method !== 'GET' || url.origin !== self.location.origin ||\n      !/^\\/media\\/videos\\/[a-f0-9]{64}\\.mp4$/.test(url.pathname)) return;\n  const range = request.headers.get('range');\n  if (range && !/^bytes=\\d+-\\d*$/.test(range)) return;\n  event.respondWith(deliver(request));\n});\n\nasync function deliver(request) {\n  const match = /^bytes=(\\d+)-(\\d*)$/.exec(request.headers.get('range') || 'bytes=0-');\n  const start = Number(match[1]);\n  const wantedEnd = match[2] ? Number(match[2]) : Infinity;\n  if (!Number.isSafeInteger(start) || wantedEnd < start) return fetch(request);\n  const abort = new AbortController();\n  const headers = new Headers(request.headers);\n  headers.set('range', `bytes=${start}-${Math.min(start + 64 * 1024 - 1, wantedEnd)}`);\n  let first;\n  try {\n    first = await fetch(request.url, {headers, signal: abort.signal, credentials:'omit'});\n  } catch {\n    return fetch(request);\n  }\n  const info = /^bytes (\\d+)-(\\d+)\\/(\\d+)$/.exec(first.headers.get('content-range') || '');\n  if (first.status !== 206 || !info || Number(info[1]) !== start) return first;\n  const total = Number(info[3]);\n  const end = Math.min(wantedEnd, total - 1);\n  const firstEnd = Number(info[2]);\n  if (firstEnd > end) return first;\n  const pending = new Map();\n  let next = firstEnd + 1;\n  let position = start;\n  let stopped = false;\n  const guarded = promise => promise.then(bytes => ({bytes}), error => ({error}));\n  pending.set(start, guarded(first.arrayBuffer().then(b => {\n    if (b.byteLength !== firstEnd - start + 1) throw Error('Incomplete first video chunk');\n    return new Uint8Array(b);\n  })));\n  async function getChunk(offset, last) {\n    for (let attempt = 0; attempt < 2; attempt++) {\n      try {\n        const h = new Headers(headers);\n        h.set('range', `bytes=${offset}-${last}`);\n        const response = await fetch(request.url, {headers:h, signal:abort.signal, credentials:'omit'});\n        if (response.status !== 206 || response.headers.get('content-range') !== `bytes ${offset}-${last}/${total}`) {\n          await response.body?.cancel();\n          throw Error('Unexpected video range');\n        }\n        const bytes = new Uint8Array(await response.arrayBuffer());\n        if (bytes.length !== last - offset + 1) throw Error('Incomplete video chunk');\n        return bytes;\n      } catch (error) {\n        if (abort.signal.aborted || attempt === 1) throw error;\n      }\n    }\n  }\n  function fill() {\n    while (!stopped && pending.size < PARALLEL && next <= end) {\n      const offset = next;\n      const last = Math.min(offset + CHUNK - 1, end);\n      next = last + 1;\n      pending.set(offset, guarded(getChunk(offset, last)));\n    }\n  }\n  fill();\n  const body = new ReadableStream({\n    async pull(controller) {\n      const result = await pending.get(position);\n      if (stopped) return;\n      if (!result || result.error) {\n        stopped = true; abort.abort(); pending.clear();\n        controller.error(result?.error || Error('Missing video chunk')); return;\n      }\n      pending.delete(position);\n      position += result.bytes.length;\n      controller.enqueue(result.bytes);\n      if (position > end) { stopped = true; pending.clear(); controller.close(); }\n      else fill();\n    },\n    cancel() { stopped = true; abort.abort(); pending.clear(); }\n  }, {highWaterMark:1});\n  const out = new Headers(first.headers);\n  out.delete('content-encoding');\n  out.set('content-length', String(end - start + 1));\n  out.set('content-range', `bytes ${start}-${end}/${total}`);\n  out.set('accept-ranges', 'bytes');\n  out.set('x-iman-video-delivery', 'parallel-ranges-v1');\n  return new Response(body, {status:206, headers:out});\n}";
const assets=new Map();
// Public styles used by the separate owner login and administration pages.
assets.set('/assets/site.css','/assets/site.css');
const pageContent=new Map();
function target(p){
  const file=path.resolve(output,'.'+p);
  if(!file.startsWith(output+path.sep))throw Error('Invalid output path');
  return file;
}
async function save(p,data){const file=target(p);await mkdir(path.dirname(file),{recursive:true});await writeFile(file,data);}
async function get(p){
  const u=new URL(p,source);
  if(publicAssetOverrides.has(u.pathname))return Buffer.from(publicAssetOverrides.get(u.pathname),'base64');
  if(u.origin!==source||/^\/(admin|api)(\/|$)/.test(u.pathname))throw Error('Nonpublic path');
  for(let attempt=0;attempt<3;attempt++){
    try{
      const r=await fetch(u,{headers:{'X-Iman-Public-Export':'1'},redirect:'error',signal:AbortSignal.timeout(120000)});
      if(!r.ok)throw Error(`${r.status}: ${u.pathname}`);
      const b=Buffer.from(await r.arrayBuffer());
      if(b.length>95*1024*1024)throw Error('Asset exceeds Pages file limit');
      return b;
    }catch(e){if(attempt===2)throw Error(`Download failed: ${u.pathname}: ${e.message}`);}
  }
}
function collect(text){
  // Existing renderer emits absolute /assets and /media paths in HTML, CSS and JS.
  for(const m of text.matchAll(/\/(?:assets|media)\/[a-zA-Z0-9_./%?=&+~-]+/g)){
    const u=new URL(m[0].replaceAll('&amp;','&'),source);
    if(!u.pathname.includes('..'))assets.set(u.pathname,u.pathname+u.search);
  }
}
const mobilePlayer="<style>.iman-video-retry{border:0;border-radius:8px;padding:12px 18px;background:#123e34;color:white;font:inherit;min-height:44px}.iman-video-retry[hidden]{display:none}.public-site .center-clip .iman-video-status{font-size:14px;line-height:1.4;margin:8px 0}.iman-video-status:empty{display:none}</style><script>/* Native controls; recovery is shown below the player only after failure. */\nconst iosVideo = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);\ndocument.querySelectorAll('.center-clip video').forEach(video => {\n  if (iosVideo) {\n    const url = new URL(video.src); url.searchParams.set('direct','1'); video.src = url.href;\n  }\n  const status = document.createElement('p');\n  status.className = 'iman-video-status'; status.setAttribute('role','status');\n  const retry = document.createElement('button');\n  retry.type='button'; retry.className='iman-video-retry'; retry.hidden=true;\n  retry.textContent='Повторить загрузку'; video.after(status, retry);\n  let timer;\n  const clear = () => clearTimeout(timer);\n  function waiting() {\n    clear(); status.textContent='Загрузка видео…';\n    timer=setTimeout(() => {\n      if (!video.paused && video.readyState < 3) {\n        status.textContent='Загрузка задерживается. Можно повторить попытку.'; retry.hidden=false;\n      }\n    },12000);\n  }\n  retry.addEventListener('click', () => {\n    const url=new URL(video.currentSrc || video.src);\n    url.searchParams.set('direct','1'); url.searchParams.set('retry',String(Date.now()));\n    video.src=url.href; video.load(); retry.hidden=true;\n    video.play()?.catch(() => { status.textContent='Нажмите кнопку воспроизведения на видео.'; });\n  });\n  video.addEventListener('play',waiting); video.addEventListener('waiting',waiting);\n  video.addEventListener('playing',()=>{clear();retry.hidden=true;status.textContent='';});\n  video.addEventListener('pause',()=>{clear();status.textContent='';});\n  video.addEventListener('error',()=>{clear();retry.hidden=false;status.textContent='Не удалось загрузить видео.';});\n});\r\n</script>";
function rewrite(s){return rewritePublicAssets(s).replaceAll(source,canonical).replace(/(<video\b[^>]*\bsrc=["'])(\/media\/videos\/[a-f0-9]{64}\.mp4)(["'])/g,'$1$2?v=20261117c$3').replace('</body>',mobilePlayer+'</body>').replace(/<link\b[^>]*rel=["'](?:shortcut )?icon["'][^>]*>/gi, '<link rel="icon" href="/favicon.png" type="image/png" sizes="120x120">').replace('</head>', "<script>if('serviceWorker' in navigator){navigator.serviceWorker.register('/video-delivery-sw.js?v=2',{updateViaCache:'none'}).catch(function(){});}</script>"+'<style id="public-presentation">'+publicStyles+'</style></head>');}
async function parallel(items,fn){
  let next=0;
  await Promise.all(Array.from({length:4},async()=>{while(next<items.length)await fn(items[next++]);}));
}
const sitemap=(await get('/sitemap.xml')).toString();
const pages=[...new Set(['/',...Array.from(sitemap.matchAll(/<loc>([^<]+)<\/loc>/g),m=>new URL(m[1]).pathname)])];
if(pages.length<10||pages.length>300)throw Error('Unexpected sitemap size');
await parallel(pages,async p=>{
  if(!/^\/[a-zA-Z0-9_/-]*$/.test(p))throw Error('Invalid page path');
  const html=rewrite((await get(p)).toString());
  if(!html.includes('</html>')||!html.includes('<main'))throw Error(`Incomplete page: ${p}`);
  collect(html);
  pageContent.set(p,html);
  await save((p==='/'?'':p.replace(/\/$/,''))+'/index.html',html);
});
const digest=createHash('sha256').update('export-v3').update(sitemap).update(JSON.stringify([...pageContent].sort(([a],[b])=>a.localeCompare(b)))).digest('hex');
let previous={};
try{previous=JSON.parse(await readFile('published.json','utf8'));}catch{}
const changed=previous.digest!==digest||process.env.FORCE_PUBLISH==='true';
if(process.env.GITHUB_OUTPUT)await appendFile(process.env.GITHUB_OUTPUT,`changed=${changed}\n`);
await writeFile('next-published.json',JSON.stringify({digest,checkedMonth:new Date().toISOString().slice(0,7)},null,2)+'\n');
if(!changed){console.log('Published content is current');process.exit(0);}
const downloaded=new Set();
while([...assets.keys()].some(p=>!downloaded.has(p))){
  await parallel([...assets.entries()].filter(([p])=>!downloaded.has(p)),async([p,url])=>{
    // Cache is a local build optimization; never use it for public HTML or uploaded photos.
    let bytes;
    if(p.startsWith('/assets/')||p.startsWith('/media/videos/')){
      try{bytes=await readFile(target(p));}catch{}
    }
    bytes??=await get(url);
    if(/\.(css|js)$/.test(p))collect(bytes.toString());
    await save(p,bytes);downloaded.add(p);
    if(downloaded.size%25===0)console.log(`Exported ${downloaded.size} assets`);
  });
}
